import{_ as t}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as a,c as r,a as o}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const f=JSON.parse(`{"title":"What's new in v1.5.0","description":"Advanced filter targets (content, path, repo), regex mode in the filter bar, word-jump shortcuts, and several TUI accuracy fixes.","frontmatter":{"title":"What's new in v1.5.0","description":"Advanced filter targets (content, path, repo), regex mode in the filter bar, word-jump shortcuts, and several TUI accuracy fixes.","date":"2026-03-01T00:00:00.000Z"},"headers":[],"relativePath":"blog/release-v1-5-0.md","filePath":"blog/release-v1-5-0.md"}`),i={name:"blog/release-v1-5-0.md"};function s(h,e,n,l,c,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-s-new-in-github-code-search-v1-5-0" tabindex="-1">What&#39;s new in github-code-search v1.5.0 <a class="header-anchor" href="#what-s-new-in-github-code-search-v1-5-0" aria-label="Permalink to &quot;What&#39;s new in github-code-search v1.5.0&quot;">​</a></h1><blockquote><p>Full release notes: <a href="https://github.com/fulll/github-code-search/releases/tag/v1.5.0" target="_blank" rel="noreferrer">https://github.com/fulll/github-code-search/releases/tag/v1.5.0</a></p></blockquote><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="advanced-filter-targets" tabindex="-1">Advanced filter targets <a class="header-anchor" href="#advanced-filter-targets" aria-label="Permalink to &quot;Advanced filter targets&quot;">​</a></h3><p>The filter bar (press <code>f</code>) can now search across three different targets. Outside filter mode, press <strong><code>t</code></strong> to cycle targets; inside the filter bar, use <strong>Shift+Tab</strong>:</p><table tabindex="0"><thead><tr><th>Badge</th><th>What is filtered</th></tr></thead><tbody><tr><td><code>[path]</code></td><td>File path of each result (default)</td></tr><tr><td><code>[content]</code></td><td>Code snippet text inside each extract</td></tr><tr><td><code>[repo]</code></td><td>Repository name (short or <code>org/repo</code> form)</td></tr></tbody></table><p>The active target badge is always visible in the filter bar, including in the default <code>[path]</code> mode, so you always know what you are filtering against.</p><h3 id="regex-mode" tabindex="-1">Regex mode <a class="header-anchor" href="#regex-mode" aria-label="Permalink to &quot;Regex mode&quot;">​</a></h3><p>Press <strong>Tab</strong> while the filter bar is open to toggle regex mode. When active, the filter input is interpreted as a regular expression — the badge shows <code>[…·regex]</code> to make it obvious. Invalid patterns match nothing gracefully (zero visible rows, no crash).</p><h3 id="word-jump-shortcuts-in-the-filter-bar" tabindex="-1">Word-jump shortcuts in the filter bar <a class="header-anchor" href="#word-jump-shortcuts-in-the-filter-bar" aria-label="Permalink to &quot;Word-jump shortcuts in the filter bar&quot;">​</a></h3><p>Three equivalent key combinations now move the cursor one word at a time:</p><ul><li><strong>⌥←/→</strong> (macOS Option+Arrow — the most natural shortcut on macOS terminals)</li><li><strong>Ctrl+←/→</strong> (common on Linux/Windows terminals)</li><li><strong>Alt+b / Alt+f</strong> (readline-style mnemonics)</li></ul><p><strong>⌥⌫</strong> (Option+Backspace) / <strong>Ctrl+W</strong> delete the word before the cursor, as before.</p><h3 id="accurate-scroll-position" tabindex="-1">Accurate scroll position <a class="header-anchor" href="#accurate-scroll-position" aria-label="Permalink to &quot;Accurate scroll position&quot;">​</a></h3><p>The viewport used by the scroll engine now accounts for the filter bar height (0–2 lines depending on the active filter mode and badge visibility). Previously, the static <code>termHeight − 6</code> estimate could cause the cursor to stop scrolling before it was actually visible. The fix ensures <code>isCursorVisible</code> uses exactly the same window as <code>renderGroups</code>.</p><h3 id="search-match-highlighting-on-the-cursor-extract-row" tabindex="-1">Search-match highlighting on the cursor extract row <a class="header-anchor" href="#search-match-highlighting-on-the-cursor-extract-row" aria-label="Permalink to &quot;Search-match highlighting on the cursor extract row&quot;">​</a></h3><p>When the cursor is positioned on an extract row, the file path now shows the search-match highlight (yellow on magenta background) — consistent with how the highlighted repo row already behaved.</p><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>Or grab the latest binary directly from the <a href="https://github.com/fulll/github-code-search/releases/tag/v1.5.0" target="_blank" rel="noreferrer">GitHub Releases page</a>.</p>',21)])])}const v=t(i,[["render",s]]);export{f as __pageData,v as default};
